import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_pipeline_primitives.h>

// Conv2d: in_channels=3, out_channels=96, kernel=11x11, stride=4, padding=2
// One fused kernel computes the whole convolution (including bias).
// Each block handles one (batch, out_channel) pair and a TILE x TILE output tile.
// The required input patch (with halo) and the filter weights are staged in
// shared memory and reused by all threads in the block.

#define TILE 16
#define KSIZE 11
#define STRIDE 4
#define PAD 2
#define CIN 3
#define OCB 16
#define PATCH ((TILE - 1) * STRIDE + KSIZE)  // 71
// Dynamic shared memory layout (avoids the 48KB static __shared__ limit):
//   [ s_in buffer 0 | s_in buffer 1 | s_w ]
// All region offsets/row strides are multiples of 4 floats (16B), keeping
// the float4 shared-memory taps 16-byte aligned exactly as before.
#define S_IN_ELEMS  (PATCH * (PATCH + 1))              // 71*72 per input buffer
#define S_W_OFF     (2 * S_IN_ELEMS)                   // start of weights region
#define S_IN(buf, r, c) dsmem[(buf) * S_IN_ELEMS + (r) * (PATCH + 1) + (c)]
#define S_W(o, r, c)    dsmem[S_W_OFF + (o) * (KSIZE * (KSIZE + 1)) + (r) * (KSIZE + 1) + (c)]
#define SMEM_BYTES  ((2 * S_IN_ELEMS + OCB * KSIZE * (KSIZE + 1)) * sizeof(float))
__global__ void __launch_bounds__(TILE * TILE, 2) conv2d_fwd_kernel(
    const float* __restrict__ input,   // N x CIN x H x W
    const float* __restrict__ weight,  // OC x CIN x K x K
    const float* __restrict__ bias,    // OC
    float* __restrict__ output,        // N x OC x OH x OW
    int N, int H, int W, int OH, int OW, int OC)
{
    // Larger 16x16 output tile with 256 threads per block to raise occupancy.
    // Register blocking: each thread accumulates a 2 (adjacent output rows)
    // x 8 (output channels) micro-tile, roughly halving the number of shared
    // memory loads per FMA compared to one-output-per-thread accumulation.
    extern __shared__ float dsmem[];
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int tid = ty * TILE + tx;
    const int nthreads = TILE * TILE;
    const int ow0 = blockIdx.x * TILE;
    const int oh0 = blockIdx.y * TILE;
    const int bz  = blockIdx.z;
    const int ocg_count = (OC + OCB - 1) / OCB;
    const int oc0 = (bz % ocg_count) * OCB;
    const int n   = bz / ocg_count;
    // Stage the channel-0 filters in shared memory (per-channel staging keeps
    // shared memory small enough to double-buffer the input patch).
    for (int i = tid; i < OCB * KSIZE * KSIZE; i += nthreads) {
        int oc_local = i / (KSIZE * KSIZE);
        int rem = i - oc_local * (KSIZE * KSIZE);
        int r   = rem / KSIZE;
        int col = rem % KSIZE;
        int oc  = oc0 + oc_local;
        float v = 0.0f;
        if (oc < OC) {
            v = weight[((oc * CIN + 0) * KSIZE + r) * KSIZE + col];
        }
        S_W(oc_local, r, col) = v;
    }
    // Zero the padded weight column (index KSIZE) so the vectorized
    // kw = 8..11 tail taps contribute exactly zero.
    for (int i = tid; i < OCB * KSIZE; i += nthreads) {
        S_W(i / KSIZE, i % KSIZE, KSIZE) = 0.0f;
    }
    // Top-left corner (in input coords) of the patch needed by this tile.
    const int in_h0 = oh0 * STRIDE - PAD;
    const int in_w0 = ow0 * STRIDE - PAD;
    // Register blocking: thread ty encodes (channel-group, row-pair).
    //   cz = ty / 8 selects output channels [cz*8, cz*8+8) of the block's 16.
    //   cy = ty % 8 selects output rows {2*cy, 2*cy+1} of the 16x16 tile.
    // All lanes of a warp share cz, so weight loads stay broadcast, while
    // each weight fetched from shared memory now feeds two FMAs.
    const int cz = ty / 8;
    const int cy = ty - cz * 8;
    const int oh_t = oh0 + 2 * cy;
    const int ow = ow0 + tx;
    const int bh0 = 2 * cy * STRIDE;
    const int bh1 = bh0 + STRIDE;
    const int bw = tx * STRIDE;
    const bool valid = (oh_t < OH) && (ow < OW);
    float acc0[OCB / 2];
    float acc1[OCB / 2];
    #pragma unroll
    for (int co = 0; co < OCB / 2; ++co) {
        acc0[co] = 0.0f;
        acc1[co] = 0.0f;
    }
    // Kick off the asynchronous (cp.async) load of channel 0 into buffer 0.
    for (int i = tid; i < PATCH * PATCH; i += nthreads) {
        int r   = i / PATCH;
        int col = i - r * PATCH;
        int ih  = in_h0 + r;
        int iw  = in_w0 + col;
        if (ih >= 0 && ih < H && iw >= 0 && iw < W) {
            __pipeline_memcpy_async(&S_IN(0, r, col),
                                    &input[((n * CIN + 0) * H + ih) * W + iw],
                                    sizeof(float));
        } else {
            S_IN(0, r, col) = 0.0f;
        }
        if (col == PATCH - 1) {
            S_IN(0, r, PATCH) = 0.0f;  // zero pad column for float4 tail taps
        }
    }
    __pipeline_commit();
    __syncthreads();
    // Channel-serial accumulation with software pipelining: while the current
    // channel is consumed from shared memory, the next channel's input patch
    // is in flight via cp.async (double buffered) and the next channel's
    // filter weights are prefetched from global memory into registers.
    for (int c = 0; c < CIN; ++c) {
        const int cur = c & 1;
        float wpre[(OCB * KSIZE * KSIZE + TILE * TILE - 1) / (TILE * TILE)];
        if (c + 1 < CIN) {
            const int nxt = cur ^ 1;
            for (int i = tid; i < PATCH * PATCH; i += nthreads) {
                int r   = i / PATCH;
                int col = i - r * PATCH;
                int ih  = in_h0 + r;
                int iw  = in_w0 + col;
                if (ih >= 0 && ih < H && iw >= 0 && iw < W) {
                    __pipeline_memcpy_async(&S_IN(nxt, r, col),
                                            &input[((n * CIN + c + 1) * H + ih) * W + iw],
                                            sizeof(float));
                } else {
                    S_IN(nxt, r, col) = 0.0f;
                }
                if (col == PATCH - 1) {
                    S_IN(nxt, r, PATCH) = 0.0f;  // zero pad column for float4 tail taps
                }
            }
            __pipeline_commit();
            #pragma unroll
            for (int j = 0; j < (OCB * KSIZE * KSIZE + TILE * TILE - 1) / (TILE * TILE); ++j) {
                int i = tid + j * nthreads;
                float v = 0.0f;
                if (i < OCB * KSIZE * KSIZE) {
                    int oc_local = i / (KSIZE * KSIZE);
                    int rem = i - oc_local * (KSIZE * KSIZE);
                    int r   = rem / KSIZE;
                    int col = rem % KSIZE;
                    int oc  = oc0 + oc_local;
                    if (oc < OC) {
                        v = weight[((oc * CIN + c + 1) * KSIZE + r) * KSIZE + col];
                    }
                }
                wpre[j] = v;
            }
            __pipeline_wait_prior(1);
        } else {
            __pipeline_wait_prior(0);
        }
        __syncthreads();
        if (valid) {
            const int cb = cz * (OCB / 2);
            // Vectorized shared-memory reads: each float4 fetch of the
            // staged input patch / filter feeds four kw taps, quartering
            // the number of shared-memory transactions per FMA. The padded
            // s_w column (index KSIZE) and the zeroed s_in pad column keep
            // the kw = 8..11 vector tail mathematically exact.
            #pragma unroll
            for (int kh = 0; kh < KSIZE; ++kh) {
                #pragma unroll
                for (int kq = 0; kq < (KSIZE + 3) / 4; ++kq) {
                    const int kw = kq * 4;
                    const float4 xv0 = *reinterpret_cast<const float4*>(&S_IN(cur, bh0 + kh, bw + kw));
                    const float4 xv1 = *reinterpret_cast<const float4*>(&S_IN(cur, bh1 + kh, bw + kw));
                    #pragma unroll
                    for (int co = 0; co < OCB / 2; ++co) {
                        const float4 wv = *reinterpret_cast<const float4*>(&S_W(cb + co, kh, kw));
                        acc0[co] += xv0.x * wv.x + xv0.y * wv.y + xv0.z * wv.z + xv0.w * wv.w;
                        acc1[co] += xv1.x * wv.x + xv1.y * wv.y + xv1.z * wv.z + xv1.w * wv.w;
                    }
                }
            }
        }
        __syncthreads();
        if (c + 1 < CIN) {
            #pragma unroll
            for (int j = 0; j < (OCB * KSIZE * KSIZE + TILE * TILE - 1) / (TILE * TILE); ++j) {
                int i = tid + j * nthreads;
                if (i < OCB * KSIZE * KSIZE) {
                    int oc_local = i / (KSIZE * KSIZE);
                    int rem = i - oc_local * (KSIZE * KSIZE);
                    int r   = rem / KSIZE;
                    int col = rem % KSIZE;
                    S_W(oc_local, r, col) = wpre[j];
                }
            }
            __syncthreads();
        }
    }
    if (valid) {
        const int cb = cz * (OCB / 2);
        const bool valid1 = (oh_t + 1 < OH);
        #pragma unroll
        for (int co = 0; co < OCB / 2; ++co) {
            const int oc = oc0 + cb + co;
            if (oc < OC) {
                const float bv = bias[oc];
                output[((n * OC + oc) * OH + oh_t) * OW + ow] = acc0[co] + bv;
                if (valid1) {
                    output[((n * OC + oc) * OH + oh_t + 1) * OW + ow] = acc1[co] + bv;
                }
            }
        }
    }
}
torch::Tensor conv2d_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {
    TORCH_CHECK(input.is_cuda() && weight.is_cuda() && bias.is_cuda(),
                "conv2d_forward: all tensors must be CUDA");
    TORCH_CHECK(input.dim() == 4, "conv2d_forward: input must be 4D (N,C,H,W)");
    TORCH_CHECK(input.size(1) == CIN, "conv2d_forward: expected 3 input channels");
    TORCH_CHECK(weight.size(1) == CIN && weight.size(2) == KSIZE && weight.size(3) == KSIZE,
                "conv2d_forward: expected weight shape (OC,3,11,11)");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "conv2d_forward: float32 only");
    auto x = input.contiguous();
    auto w = weight.contiguous();
    auto b = bias.contiguous();
    const int N  = x.size(0);
    const int H  = x.size(2);
    const int W  = x.size(3);
    const int OC = w.size(0);
    const int OH = (H + 2 * PAD - KSIZE) / STRIDE + 1;
    const int OW = (W + 2 * PAD - KSIZE) / STRIDE + 1;
    const int OCG = (OC + OCB - 1) / OCB;
    TORCH_CHECK(OH > 0 && OW > 0, "conv2d_forward: invalid output size");
    TORCH_CHECK((long)N * OCG <= 65535, "conv2d_forward: N*ceil(OC/OCB) exceeds grid.z limit");
    auto out = torch::empty({N, OC, OH, OW}, x.options());
    // Opt in to >48KB of dynamic shared memory (static __shared__ is capped at 48KB).
    static bool smem_configured = []() {
        cudaError_t err = cudaFuncSetAttribute(
            conv2d_fwd_kernel,
            cudaFuncAttributeMaxDynamicSharedMemorySize,
            (int)SMEM_BYTES);
        TORCH_CHECK(err == cudaSuccess,
                    "conv2d_forward: cudaFuncSetAttribute failed: ",
                    cudaGetErrorString(err));
        return true;
    }();
    (void)smem_configured;
    dim3 block(TILE, TILE);
    dim3 grid((OW + TILE - 1) / TILE, (OH + TILE - 1) / TILE, N * OCG);
    conv2d_fwd_kernel<<<grid, block, SMEM_BYTES, at::cuda::getCurrentCUDAStream()>>>(
        x.data_ptr<float>(), w.data_ptr<float>(), b.data_ptr<float>(),
        out.data_ptr<float>(), N, H, W, OH, OW, OC);
    return out;
}
"""

cpp_src = "torch::Tensor conv2d_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias);"

_conv_mod = load_inline(
    name="conv2d_custom_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["conv2d_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)

    def forward(self, x):
        in_device = x.device
        w = self.conv1.weight
        b = self.conv1.bias
        if not x.is_cuda:
            x = x.cuda()
        if not w.is_cuda:
            w = w.cuda()
            b = b.cuda()
        if x.dtype != torch.float32:
            x = x.float()
        out = _conv_mod.conv2d_forward(x, w, b)
        if out.device != in_device:
            out = out.to(in_device)
        return out

